+import static org.mockito.Mockito.verify;
+
+/** UC-002: directory rendering, bounded loading, and failure behavior. */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @MockitoSpyBean
+    private VetRepository repository;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void menuOpensDirectoryWithNamesAndAlphabeticalSpecialties() {
+        navigate(WelcomeView.class);
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected the veterinarian navigation link");
+        UI.getCurrent().navigate(link.getPath());
+
+        var grid = test(grid());
+        assertEquals("vets", UI.getCurrent().getActiveViewLocation().getPath());
+        assertEquals(6, grid.size());
+        assertEquals("James", grid.getCellText(0, 0));
+        assertEquals("Carter", grid.getCellText(0, 1));
+        assertEquals("none", grid.getCellText(0, 2));
+        assertEquals("Linda", grid.getCellText(1, 0));
+        assertEquals("Douglas", grid.getCellText(1, 1));
+        assertEquals("dentistry, surgery", grid.getCellText(1, 2));
+        assertEquals("radiology", grid.getCellText(3, 2));
+        assertEquals(6, dsl.fetchCount(VETS));
+        assertEquals(5, dsl.fetchCount(VET_SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void providerFetchesBoundedNonOverlappingPages() {
+        for (int i = 0; i < 123; i++) {
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                    .values("Same", "Name").execute();
+        }
+        navigate(VetsView.class);
+        var provider = grid().getDataProvider();
+        assertFalse(provider.isInMemory());
+        assertEquals(129, provider.size(new Query<>()));
+
+        List<Vet> first = provider.fetch(new Query<>(0, 50, List.of(), null, null)).toList();
+        List<Vet> second = provider.fetch(new Query<>(50, 50, List.of(), null, null)).toList();
+        List<Vet> last = provider.fetch(new Query<>(100, 50, List.of(), null, null)).toList();
+        assertEquals(50, first.size());
+        assertEquals(50, second.size());
+        assertEquals(29, last.size());
+        assertEquals(129, java.util.stream.Stream.of(first, second, last)
+                .flatMap(List::stream).map(Vet::id).distinct().count());
+        assertEquals(second, provider.fetch(new Query<>(50, 50, List.of(), null, null)).toList());
+        assertTrue(provider.fetch(new Query<>(129, 50, List.of(), null, null)).toList().isEmpty());
+        verify(repository).findPage(100, 50);
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryRendersAnEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+        navigate(VetsView.class);
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
