+        navigate(VetsView.class);
+        var provider = grid().getDataProvider();
+        assertEquals(2, provider.fetch(new Query<>(0, 2, List.of(), null, null)).count());
+        doThrow(new DataAccessResourceFailureException("Directory unavailable"))
+                .when(repository).findPage(2, 2);
+        provider.fetch(new Query<>(2, 2, List.of(), null, null)).toList();
+        assertErrorView();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> grid() {
+        return assertDoesNotThrow(() -> find(Grid.class).single(),
