+    private void assertErrorView() {
+        assertDoesNotThrow(() -> find(ApplicationErrorView.class).single(),
+                "Expected the application error view");
+        assertEquals(0, find(Grid.class).all().size(), "No veterinarian list remains after failure");
+    }
